import { join } from "node:path";
import BetterSqlite3 from "better-sqlite3";
import type { Database } from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { Kysely, SqliteDialect } from "kysely";
import type { DB } from "./kysely-types.ts";

/** Generated by `pnpm db:generate`; resolved from this file so tests, `pnpm dev` and the container agree. */
export const MIGRATIONS_DIR = join(import.meta.dirname, "..", "..", "drizzle");

export interface Db {
  sqlite: Database;
  kysely: Kysely<DB>;
}

export function openDatabase(path: string): Db {
  const sqlite = new BetterSqlite3(path);
  sqlite.pragma("busy_timeout = 5000");
  if (path !== ":memory:") sqlite.pragma("journal_mode = WAL");
  sqlite.pragma("foreign_keys = ON");
  migrate(drizzle(sqlite), { migrationsFolder: MIGRATIONS_DIR });
  return { sqlite, kysely: new Kysely<DB>({ dialect: new SqliteDialect({ database: sqlite }) }) };
}

export async function closeDatabase(db: Db): Promise<void> {
  await db.kysely.destroy();
}
